 public static function callBack(array$request):PBXApiResult{$actionString=(string)($request['action']??'');$action=JobAction::tryFrom($actionString);$data=WorkerRequestContext::data($request);if(WorkerRequestContext::isRevokedWorkerKey($data))return self::error('worker_resource_forbidden','Worker credentials cannot manage jobs',403);return match($action){JobAction::GET_NEXT=>LegacyRouteRejector::worker(),JobAction::DOWNLOAD=>LegacyRouteRejector::worker(),JobAction::SUBMIT_RESULT=>LegacyRouteRejector::worker(),JobAction::SUBMIT_ERROR=>LegacyRouteRejector::worker(),JobAction::HEARTBEAT=>LegacyRouteRejector::worker(),JobAction::RELEASE=>LegacyRouteRejector::worker(),default=>(static function()use($request,$actionString,$action,$data):PBXApiResult{if(WorkerRequestContext::isRestrictedWorkerKey($data)||!WorkerRequestContext::isAdministrator($data))return self::error('worker_resource_forbidden','Worker credentials cannot manage jobs',403);if(!$action instanceof JobAction)return self::error('unknown_action','Unknown action',400);$id=(int)($data['id']??0);if(in_array($action,[JobAction::PATCH,JobAction::DELETE],true)&&array_key_exists('_idFromRequestBody',$data)&&!CanonicalJobId::matchesRoute($data['_idFromRequestBody'],$id))return self::error('job_id_mismatch','Body job ID does not match route',409);$gate=new ModuleLifecycleGate();$lease=$gate->acquireWriteLease();if($lease===null){$result=self::error('module_unavailable','Module is temporarily unavailable',503);$result->data['retry_after']=5;return$result;}try{(new ModuleDatabasePragmas())->configureRuntime((new STTJob())->getWriteConnection());$service=new STTJobManagementService();$result=match($action){JobAction::GET_LIST=>$service->getList($data),JobAction::GET_RECORD=>$service->getRecord($id),JobAction::CREATE=>$service->create($data),JobAction::PATCH=>$service->patch($id,$data),JobAction::PATCH_COLLECTION=>$service->patchCollection($data),JobAction::DELETE=>$service->delete($id),JobAction::DELETE_COLLECTION=>$servi